      SUBROUTINE RDLINEC---- READ INPUT LINE AND PRINT ECHOC-------------------------------------------------------------------      INCLUDE 'DATA2A.CIN'      INCLUDE 'IODATA.CIN'      INCLUDE 'IOFLAG.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'RDBUFF.CIN'      INCLUDE 'RDPRNT.CIN'C-------------------------------------------------------------------C      IF (.NOT. ENDFIL) THEN        IF (NEL .EQ. 0 .OR. INDS .NE. 0 .OR. .NOT. ECHO .OR. RFM)     1      GO TO 10        IF (MOD(ILINE,5) .EQ. 0) THEN          WRITE (NOUT,9140) NEL 9140     FORMAT (1H+,95X,1H(,I4,' ELEMENTS)')        ELSE          WRITE (NOUT,9141) NEL 9141     FORMAT (1H+,95X,1H(,I4,9X,')')        ENDIFC   10   READ (NIN,910,IOSTAT=ISTAT) KTEXT        ILINE = ILINE + 1        IMARK = 1        ICOL = 0CC---- READ ERROR?C        IF (ISTAT .GT. 0) THEN          WRITE (NOUT,920) ILINE          NFAIL = NFAIL + 1          ENDFIL = .TRUE.CC---- END OF FILE?C        ELSE IF (ISTAT .LT. 0) THEN          ENDFIL = .TRUE.          KTEXT = ']]] END OF FILE ]]]'          ICOL = 1          ITEM = KLINE(ICOL)CC---- READ WAS OKC        ELSE IF (ECHO .AND. .NOT. RFM) THEN          IF (MOD(ILINE,5) .EQ. 0) THEN            WRITE (NOUT,930) ILINE, KTEXT          ELSE            WRITE (NOUT,940) KTEXT          ENDIF        ENDIF        CALL UCTABS(KTEXT)        KLINE(81) = ';'      ENDIF      RETURNC-------------------------------------------------------------------  910 FORMAT(A80)  920 FORMAT('0*** ERROR *** READ ERROR ON LOGICAL UNIT ',I2,     +       ', LINE ',I4,' --- EXECUTION TERMINATED')  930 FORMAT(' ',I5,5X,A80)  940 FORMAT(11X,A80)C-------------------------------------------------------------------      END